<script setup lang="ts">
import {computed,ref,shallowRef,watch} from 'vue'
import {ApiError} from '@/core/http'
import {can,currentProject,projectId,session} from '@/core/session'
import {formatTime} from '@/core/time'
import {useResource} from '@/core/use-resource'
import AsyncState from '@/ui/AsyncState.vue'
import CursorPager from '@/ui/CursorPager.vue'
import {statusLabel} from '../devices/api'
import {alarmLabel} from '../devices/page-alarm-status'
import {validOtaName} from './ota-management-metadata-api'
import type {OtaFirmware} from './ota-read-api'
import type {OtaManualDispatchMode} from './ota-manual-dispatch-api'
import {otaUpgradeStatisticsTransport,otaUpgradeMetrics,otaUpgradeOrders,otaUpgradeMetricLabel,otaUpgradeOrderLabel,otaUpgradeReasonLabel,type OtaUpgradeStatisticsTransport,type OtaUpgradeMetric,type OtaUpgradeDevicesQuery,type OtaUpgradeCurrentDevice,type OtaUpgradeDevice} from './ota-upgrade-statistics-api'
const props=withDefaults(defineProps<{firmware:OtaFirmware;active:boolean;overview?:boolean;disabled?:boolean;refreshKey?:number;initialMetric?:OtaUpgradeMetric;transport?:OtaUpgradeStatisticsTransport}>(),{initialMetric:'ALL_RELATED',transport:()=>otaUpgradeStatisticsTransport})
const emit=defineEmits<{open:[metric:OtaUpgradeMetric];dispatch:[device:OtaUpgradeDevice,mode:OtaManualDispatchMode]}>()
const readable=computed(()=>session.ready&&!session.transitioning&&!!session.user?.accountId&&props.firmware.projectId===projectId.value&&can('ota:read')&&['OWNER','ADMIN'].includes(session.user?.projectRole||'')&&['OWNER','ADMIN'].includes(currentProject.value?.myRole||''))
const mayDispatch=computed(()=>readable.value&&currentProject.value?.status==='ACTIVE'&&can('ota:deploy'))
const keyword=ref(''),status=ref<''|'ONLINE'|'OFFLINE'|'INACTIVE'>(''),metric=ref<OtaUpgradeMetric>(props.initialMetric),order=ref<OtaUpgradeDevicesQuery['order']>('LAST_DELIVERED_DESC'),validation=ref('')
const query=shallowRef<OtaUpgradeDevicesQuery>()
let generation=0
const summary=useResource(signal=>props.transport.read(projectId.value,props.firmware,signal))
const devices=useResource(signal=>{if(!query.value)throw new Error('请选择设备范围');return props.transport.devices(projectId.value,props.firmware,query.value,signal)})
const forbidden=computed(()=>!readable.value||summary.error.value instanceof ApiError&&[401,403].includes(summary.error.value.status))
const deviceForbidden=computed(()=>!readable.value||devices.error.value instanceof ApiError&&[401,403].includes(devices.error.value.status))
const cards=computed(()=>{const row=summary.data.value;return row?[{label:'当前可升级设备数',value:row.currentUpgradeableCount,metric:'CURRENT_UPGRADEABLE' as const},{label:'已下发升级设备总数',value:row.deliveredCount,metric:'DELIVERED' as const},{label:'已下发未升级设备数',value:row.deliveredNotSucceededCount,metric:'DELIVERED_NOT_SUCCEEDED' as const},{label:'已成功升级设备数',value:row.succeededCount,metric:'SUCCEEDED' as const}]:[]})
function versionLabel(row:OtaUpgradeCurrentDevice){const version=row.version;return version===null?'未声明版本属性':version.state==='VALUE'?(version.rawValue===''?'（空字符串）':version.rawValue):version.state==='NO_VALUE'?'未上报':'未确认'}
function relatedLabel(value:OtaUpgradeDevice['relatedState']){return {NOT_DELIVERED:'未下发',DELIVERED_NOT_SUCCEEDED:'已下发未确认成功',SUCCEEDED:'已成功升级'}[value]??value}
function dispatchMode(row:OtaUpgradeDevice):OtaManualDispatchMode|undefined{return row.currentEligible===true?(row.relatedState==='NOT_DELIVERED'?'INITIAL':row.relatedState==='DELIVERED_NOT_SUCCEEDED'?'REDISPATCH':undefined):undefined}
function dispatch(row:OtaUpgradeDevice){const mode=dispatchMode(row);if(!props.active||!mayDispatch.value||props.disabled||!mode||!devices.data.value?.items.includes(row))return;emit('dispatch',row,mode)}
function loadDevices(){devices.clear();if(readable.value&&props.active&&query.value)void devices.reload()}
async function reload(){const g=++generation;summary.clear();devices.clear();query.value=undefined;keyword.value='';status.value='';order.value='LAST_DELIVERED_DESC';validation.value='';metric.value=props.initialMetric;if(!readable.value||!props.active)return;await summary.reload();if(g!==generation||!readable.value||!props.active||!summary.data.value)return;if(props.overview){query.value=Object.freeze({metric:'SUCCEEDED',order:'LAST_SUCCEEDED_DESC',page:1,limit:10})}else{if(summary.data.value.eligibilityState==='UNAVAILABLE'&&metric.value==='ALL_RELATED')metric.value='DELIVERED';query.value=Object.freeze({metric:metric.value,order:order.value,page:1,limit:20})}loadDevices()}
function choose(value:OtaUpgradeMetric){if(!readable.value||!props.active)return;if(props.overview){emit('open',value);return}metric.value=value;keyword.value='';status.value='';order.value='LAST_DELIVERED_DESC';filter()}
function filter(){if(!readable.value||!props.active||props.overview)return;validation.value='';if(keyword.value!==''&&(keyword.value.length>128||!validOtaName(keyword.value))){validation.value='关键词须为不超过128个字符的有效文本';return}query.value=Object.freeze({metric:metric.value,keyword:keyword.value||undefined,status:status.value||undefined,order:order.value,page:1,limit:query.value?.limit??20});loadDevices()}
function turn(page:number){if(!query.value||!Number.isInteger(page)||page<1||page>2147483647||devices.loading.value)return;query.value=Object.freeze({...query.value,page});loadDevices()}
function resize(limit:number){if(!query.value||![20,50,100,200].includes(limit)||devices.loading.value)return;query.value=Object.freeze({...query.value,limit,page:1});loadDevices()}
watch([()=>projectId.value,()=>props.firmware,()=>session.user?.accountId,readable,()=>props.active,()=>props.initialMetric,()=>props.overview,()=>props.refreshKey,()=>props.transport],()=>{void reload()},{immediate:true,flush:'sync'})
</script>
<template><section v-if="active" class="ota-upgrade-statistics"><header><h3>OTA 升级统计</h3><el-button :loading="summary.loading.value" :disabled="!readable" @click="reload">刷新升级统计</el-button></header><p class="help">下发按消息服务已确认接受统计，不代表设备已收到。成功采用平台确认的受保护安装结果，比仅上报目标版本的口径更严格。</p><AsyncState :forbidden="forbidden" :loading="summary.loading.value" :error="summary.error.value" @retry="reload"><template v-if="summary.data.value"><div class="metric-cards"><button v-for="card in cards" :key="card.metric" type="button" class="metric-card" :aria-label="card.label" @click="choose(card.metric)"><span>{{card.label}}</span><strong>{{card.value??'未确认'}}</strong></button><div class="metric-card"><span>升级成功率</span><strong>{{summary.data.value.deliveredSuccessPercentage===null?'—':summary.data.value.deliveredSuccessPercentage+'%'}}</strong></div><div class="metric-card"><span>升级完成度</span><strong>{{summary.data.value.overallSuccessPercentage===null?'—':summary.data.value.overallSuccessPercentage+'%'}}</strong></div></div><p class="help">统计观察时间：{{formatTime(summary.data.value.observedAt)}} · 资格检查时间：{{formatTime(summary.data.value.checkedAt)}}。比例的分母为0时显示“—”。</p><p v-if="summary.data.value.eligibilityReason" :role="summary.data.value.eligibilityState==='UNAVAILABLE'?'status':undefined" class="help">{{otaUpgradeReasonLabel(summary.data.value.eligibilityReason)}}<template v-if="summary.data.value.eligibilityState==='UNAVAILABLE'">；当前可升级范围和完成度尚未确认，已下发历史仍可读取。</template></p><details v-if="summary.data.value.unlinkedProtectedSuccessCount!=='0'" class="help"><summary>下发确认诊断</summary><p>另有 {{summary.data.value.unlinkedProtectedSuccessCount}} 台设备存在受保护成功记录，但缺少可关联的下发确认；单独列示，不计入已确认下发或成功率。</p></details></template></AsyncState>
<template v-if="summary.data.value"><h4>{{overview?'最新成功升级设备':'相关设备'}}</h4><p class="help">{{overview?'按最近的受保护成功时间，最多显示10台。':'仅展示本次范围的真实设备，筛选与分页由服务端执行。'}}</p><form v-if="!overview" class="statistics-filters" @submit.prevent="filter"><el-select v-model="metric" aria-label="升级统计设备范围"><el-option v-for="value in otaUpgradeMetrics" :key="value" :value="value" :label="otaUpgradeMetricLabel(value)"/></el-select><el-input v-model="keyword" aria-label="升级统计设备关键词" placeholder="设备名称、ID或标识" maxlength="128"/><el-select v-model="status" aria-label="升级统计设备状态"><el-option value="" label="不限设备状态"/><el-option value="INACTIVE" label="未激活"/><el-option value="ONLINE" label="在线"/><el-option value="OFFLINE" label="离线"/></el-select><el-select v-model="order" aria-label="升级统计设备排序"><el-option v-for="value in otaUpgradeOrders" :key="value" :value="value" :label="otaUpgradeOrderLabel(value)"/></el-select><el-button native-type="submit" :loading="devices.loading.value">查询相关设备</el-button></form><p v-if="validation" role="alert">{{validation}}</p><AsyncState :forbidden="deviceForbidden" :loading="devices.loading.value" :error="devices.error.value" @retry="loadDevices"><template v-if="devices.data.value"><p v-if="!overview">共 {{devices.data.value.total}} 台设备</p><p class="help">设备列表观察时间：{{formatTime(devices.data.value.observedAt)}}。列表与指标分别读取，数量可能随新事实变化。</p><el-empty v-if="!devices.data.value.items.length" :description="overview?'尚无已确认的成功升级设备':'当前条件无相关设备'" :image-size="48"/><el-table v-else :data="devices.data.value.items" border><el-table-column label="设备名称" min-width="165"><template #default="{row}"><template v-if="row.current"><router-link v-if="can('device:read')" :to="`/devices/${row.deviceId}`">{{row.current.name}}</router-link><span v-else>{{row.current.name}}</span><p class="help">{{row.current.deviceKey}}</p></template><template v-else><span>{{row.deviceId}}</span><p class="help">当前不在该设备类型</p></template></template></el-table-column><el-table-column v-if="!overview" label="业务标识" min-width="130"><template #default="{row}">{{row.current?.businessKey??'—'}}</template></el-table-column><el-table-column v-if="!overview" label="设备状态" min-width="90"><template #default="{row}">{{row.current?statusLabel(row.current.status):'—'}}</template></el-table-column><el-table-column label="当前上报版本" min-width="140"><template #default="{row}"><span class="version-value">{{row.current?versionLabel(row.current):'—'}}</span></template></el-table-column><el-table-column label="升级状态" min-width="150"><template #default="{row}">{{relatedLabel(row.relatedState)}}<p v-if="!overview" class="help">{{row.currentEligible===null?'当前资格未确认':row.currentEligible?'当前符合升级条件':'当前不符合升级条件'}}</p></template></el-table-column><el-table-column v-if="!overview" label="首次下发确认" min-width="165"><template #default="{row}">{{formatTime(row.firstDeliveredAt)}}</template></el-table-column><el-table-column v-if="!overview" label="最近下发确认" min-width="165"><template #default="{row}">{{formatTime(row.lastDeliveredAt)}}</template></el-table-column><el-table-column label="最近安装成功" min-width="165"><template #default="{row}">{{formatTime(row.lastSucceededAt)}}</template></el-table-column><el-table-column v-if="!overview" label="告警" min-width="110"><template #default="{row}">{{row.current?alarmLabel(row.current.alarm.state==='UNKNOWN'?undefined:row.current.alarm.state):'—'}}</template></el-table-column><el-table-column v-if="mayDispatch&&!overview" label="操作" width="115" fixed="right"><template #default="{row}"><el-button v-if="dispatchMode(row)" link type="primary" :disabled="disabled" @click="dispatch(row)">{{dispatchMode(row)==='INITIAL'?'下发升级':'重新下发'}}</el-button></template></el-table-column></el-table><CursorPager v-if="!overview" :page="query!.page" :limit="query!.limit" :total="devices.data.value.total" :sizes="[20,50,100,200]" :loading="devices.loading.value" @update:page="turn" @update:limit="resize"/></template></AsyncState><el-button v-if="overview" link type="primary" @click="emit('open','SUCCEEDED')">查看更多升级设备</el-button></template></section></template>
<style scoped>.ota-upgrade-statistics{margin:24px 0}.ota-upgrade-statistics header{display:flex;align-items:center;justify-content:space-between;gap:12px}.ota-upgrade-statistics h3{font-size:17px;font-weight:500}.ota-upgrade-statistics h4{font-size:15px;font-weight:500;margin-top:24px}.help{font-size:12px;line-height:20px;color:var(--tl-muted);overflow-wrap:anywhere}.metric-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:16px 0}.metric-card{display:flex;flex-direction:column;align-items:flex-start;gap:14px;padding:18px;border:1px solid var(--el-border-color);border-radius:4px;background:var(--el-bg-color);text-align:left;color:var(--tl-text);min-width:0}.metric-card span{font-size:13px;color:var(--tl-muted)}.metric-card strong{font-size:25px;font-weight:500;overflow-wrap:anywhere}button.metric-card{cursor:pointer}button.metric-card:hover{border-color:var(--tl-primary)}.statistics-filters{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.statistics-filters .el-input{width:230px}.statistics-filters .el-select{width:185px}.version-value{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:650px){.metric-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.statistics-filters .el-input,.statistics-filters .el-select{width:100%}}</style>
